/**
 * QtPi Compatibility Bridge for Modern Blockly (Raspberry Pi Foundation)
 */
(function() {
  if (typeof window !== "undefined") {
    window.goog = window.goog || {
      provide: function(ns) {
        var curr = window;
        var parts = ns.split(".");
        for (var i = 0; i < parts.length; i++) {
          if (!curr[parts[i]]) curr[parts[i]] = {};
          curr = curr[parts[i]];
        }
      },
      require: function() {}
    };

    if (window.Blockly) {
      // Alignment constants
      window.Blockly.ALIGN_LEFT = -1;
      window.Blockly.ALIGN_CENTRE = 0;
      window.Blockly.ALIGN_RIGHT = 1;

      // Ensure block namespaces
      window.Blockly.Blocks = window.Blockly.Blocks || {};
      window.Blockly.Blocks.dicts = window.Blockly.Blocks.dicts || {};
      window.Blockly.Blocks.dicts.HUE = 345;

      // Mutator shim
      window.Blockly.Mutator = function(quarkNames) {
        this.quarkNames = quarkNames || [];
        this.quarkNames_ = quarkNames || [];
      };
      window.Blockly.Mutator.reconnect = function(connection, block, inputName) {
        if (!connection || !block) return false;
        var input = block.getInput(inputName);
        if (input && input.connection && connection) {
          try {
            input.connection.connect(connection);
            return true;
          } catch (e) {
            return false;
          }
        }
        return false;
      };

      // Wrap setMutator on BlockSvg or Block to bridge with Blockly.icons.MutatorIcon
      var blockSvgProto = window.Blockly.BlockSvg ? window.Blockly.BlockSvg.prototype : (window.Blockly.Block ? window.Blockly.Block.prototype : null);
      if (blockSvgProto && !blockSvgProto._origSetMutator) {
        blockSvgProto._origSetMutator = blockSvgProto.setMutator;
        blockSvgProto.setMutator = function(mutator) {
          if (mutator && window.Blockly.icons && window.Blockly.icons.MutatorIcon && !(mutator instanceof window.Blockly.icons.MutatorIcon)) {
            var quarkNames = mutator.quarkNames || mutator.quarkNames_ || [];
            try {
              mutator = new window.Blockly.icons.MutatorIcon(quarkNames, this);
            } catch (e) {
              mutator = null;
            }
          }
          if (mutator && this._origSetMutator) {
            try {
              return this._origSetMutator(mutator);
            } catch (e) {
              // safe fallback
            }
          }
        };
      }

      // Dictionary & UI Message fallbacks
      window.Blockly.Msg = window.Blockly.Msg || {};
      var msgDefaults = {
        DICTS_CREATE_EMPTY_TITLE: "create empty dictionary",
        DICTS_CREATE_WITH_INPUT_WITH: "create dictionary with",
        DICTS_CREATE_WITH_CONTAINER_TITLE_ADD: "dictionary",
        DICTS_CREATE_WITH_ITEM_TITLE: "item",
        DICTS_CREATE_WITH_TOOLTIP: "Create a dictionary with any number of items.",
        DICTS_ADD_OR_CHANGE: "add or change key",
        DICTS_ADD_VALUE: "value",
        DICTS_ADD_TOOLTIP: "Add or change a key-value pair in dictionary.",
        DICTS_DELETE_TOOLTIP: "Delete a key from dictionary.",
        DICTS_SET_DEFAULT: "set default value",
        DICTS_DEFAULT_VALUE: "default value",
        DICTS_SETDEFAULT_TOOLTIP: "Set default value for key if not present.",
        LISTS_GET_SUBLIST_HELPURL: ""
      };
      for (var k in msgDefaults) {
        if (!window.Blockly.Msg[k]) {
          window.Blockly.Msg[k] = msgDefaults[k];
        }
      }

      // Python Generator Proxy
      if (window.Blockly.Python) {
        var py = window.Blockly.Python;
        if (!py.forBlock) py.forBlock = {};
        if (typeof Proxy !== "undefined") {
          window.Blockly.Python = new Proxy(py, {
            set: function(target, prop, value) {
              target[prop] = value;
              if (typeof value === "function" && target.forBlock) {
                target.forBlock[prop] = value;
              }
              return true;
            },
            get: function(target, prop) {
              if (prop in target) return target[prop];
              if (target.forBlock && prop in target.forBlock) return target.forBlock[prop];
              return undefined;
            }
          });
        }
      }
    }
  }
})();


